    /// A fine checker laid into a deep perspective is the grey it
    /// averages to from end to end — a near end shrunk to a quarter and
    /// a far end to a fortieth, which is past the eight taps a side a
    /// pixel can take of the picture itself: there it was a moiré.
    /// Read from the pyramid's levels, a level for each pixel and mixed
    /// between two, it is flat however deep the shrink, and with no step
    /// where one level gives way to the next.
    #[test]
    fn a_checker_in_deep_perspective_is_grey_from_end_to_end() {
        const N: u32 = 1024;
        let mut bytes = Vec::with_capacity((N * N * 4) as usize);
        for y in 0..N {
            for x in 0..N {
                let v = if (x + y) % 2 == 0 { 255 } else { 0 };
                bytes.extend_from_slice(&[v, v, v, 255]);
            }
        }
        let mut doc = Document::new(270, 60, ColorMode::Rgb);
        let rid = doc.add_resource(N, N, bytes);
        let root = doc.root();
        let n = N as f32;
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(Node::raster(
                "road",
                chitrakar_doc::RasterRef {
                    resource_id: rid,
                    width: N,
                    height: N,
                    // A road going away: its near edge 250 wide along the
                    // bottom, its far one 25 along the top — shrunk by four
                    // across at the near end and by forty at the far, and
                    // down it by more than two everywhere.
                    corners: Some([[n * 0.45, 0.0], [n * 0.55, 0.0], [n, n], [0.0, n]]),
                },
            )),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id,
            transform: Transform {
                a: 250.0 / n,
                d: 45.0 / n,
                e: 10.0,
                f: 5.0,
                ..Default::default()
            },
        })
        .unwrap();
        let s = render(&doc).unwrap();
        // Down the middle of the road, from the near end to the far.
        let mut worst = (0.0f32, 0);
        for y in 6..49 {
            for x in [130u32, 135, 140] {
                let off = (s.get(x, y).r - 0.5).abs();
                if off > worst.0 {
                    worst = (off, y);
                }
            }
        }
        assert!(
            worst.0 < 0.01,
            "the grey is {} off at row {}",
            worst.0,
            worst.1
        );
    }

    /// Down a road in perspective a picture blurs as it goes away, and it
    /// blurs smoothly: where one level of its pyramid gives way to the
    /// next, a pixel is read from both and mixed by how far between them
    /// it is. Read from one or the other, the line where they meet is a
    /// step in how sharp the picture is — a seam across the road.
    /// Measured as the stripes' contrast, row by row, which should fall
    /// away with the distance and never jump.
    #[test]
    fn a_picture_going_away_blurs_without_a_seam() {
        const N: u32 = 512;
        let mut bytes = Vec::with_capacity((N * N * 4) as usize);
        for _ in 0..N {
            for x in 0..N {
                let wave = 0.5 + 0.5 * (x as f32 * std::f32::consts::TAU / 64.0).sin();
                let v = (wave * 255.0).round() as u8;
                bytes.extend_from_slice(&[v, v, v, 255]);
            }
        }
        let mut doc = Document::new(140, 50, ColorMode::Rgb);
        let rid = doc.add_resource(N, N, bytes);
        let root = doc.root();
        let n = N as f32;
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(Node::raster(
                "road",
                chitrakar_doc::RasterRef {
                    resource_id: rid,
                    width: N,
                    height: N,
                    corners: Some([[n * 0.375, 0.0], [n * 0.625, 0.0], [n, n], [0.0, n]]),
                },
            )),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id,
            transform: Transform {
                a: 128.0 / n,
                d: 40.0 / n,
                e: 6.0,
                f: 5.0,
                ..Default::default()
            },
        })
        .unwrap();
        let s = render(&doc).unwrap();
        // The middle of each row, where every row is still road.
        let contrast: Vec<f32> = (6..44)
            .map(|y| {
                let (mut lo, mut hi) = (f32::MAX, f32::MIN);
                for x in 58..82 {
                    let v = s.get(x, y).r;
                    lo = lo.min(v);
                    hi = hi.max(v);
                }
                hi - lo
            })
            .collect();
        let jump = contrast
            .windows(2)
            .map(|w| (w[1] - w[0]).abs())
            .fold(0.0f32, f32::max);
        // Blended, the most it moves between two rows is under 0.04 — the
        // stripes' period sliding against the window — and with the levels
        // read one or the other, 0.09.
        assert!(
            jump < 0.06,
            "the stripes' contrast jumps by {jump} from one row to the next: {contrast:?}"
        );
    }

    /// A picture whose corners are moved to where a plain shrink would
    /// put them is drawn as the plain shrink is: the two read the same
    /// levels of the same pyramid with the same arithmetic, the moved
    /// corners only finding their level pixel by pixel. At a power of two,
    /// where a pixel is wholly on one level; between two, the moved
    /// picture mixes the two levels (a seam across a road otherwise) and
    /// the plain one, all of it on one, does not.
    #[test]
    fn corners_moved_to_a_shrink_draw_the_shrink() {
        const N: u32 = 240;
        let bytes: Vec<u8> = (0..N * N * 4)
            .map(|i| {
                if i % 4 == 3 {
                    255
                } else {
                    ((i as u64 * 53 + 7) % 251) as u8
                }
            })
            .collect();
        for shrink in [2.0f32, 4.0, 8.0] {
            let place = |corners: Option<[[f32; 2]; 4]>, t: Transform| {
                let mut doc = Document::new(80, 80, ColorMode::Rgb);
                let rid = doc.add_resource(N, N, bytes.clone());
                let root = doc.root();
                doc.apply(Command::AddNode {
                    parent: root,
                    index: 0,
                    node: Box::new(Node::raster(
                        "img",
                        chitrakar_doc::RasterRef {
                            resource_id: rid,
                            width: N,
                            height: N,
                            corners,
                        },
                    )),
                })
                .unwrap();
                let id = doc.children_of(root).unwrap()[0];
                doc.apply(Command::SetTransform { id, transform: t })
                    .unwrap();
                render(&doc).unwrap()
            };
            let side = N as f32 / shrink;
            let plain = place(
                None,
                Transform {
                    a: 1.0 / shrink,
                    d: 1.0 / shrink,
                    e: 2.0,
                    f: 2.0,
                    ..Default::default()
                },
            );
            let moved = place(
                Some([[0.0, 0.0], [side, 0.0], [side, side], [0.0, side]]),
                Transform::translation(2.0, 2.0),
            );
            let inside = (side.floor() as u32).min(78);
            let mut worst = 0.0f32;
            for y in 3..inside {
                for x in 3..inside {
                    let (p, q) = (plain.get(x, y), moved.get(x, y));
                    worst = worst
                        .max((p.r - q.r).abs())
                        .max((p.g - q.g).abs())
                        .max((p.b - q.b).abs());
                }
            }
            assert!(
                worst < 0.03,
                "shrunk by {shrink}: the two differ by {worst}"
            );
        }
    }

    /// A picture with its corners moved is drawn through them: where
    /// the corners are the rectangle's it is the picture it was, a
    /// trapezoid covers a trapezoid with its edges covered by area, the
    /// far end of a perspective averages what it squeezes rather than
    /// aliasing it, and its box and its hits are the quad's.
    #[test]
    fn a_picture_goes_where_its_corners_are_put() {
        let picture = |doc: &mut Document, bytes: Vec<u8>, w: u32, h: u32, corners| {
            let rid = doc.add_resource(w, h, bytes);
            let root = doc.root();
            doc.apply(Command::AddNode {
                parent: root,
                index: 0,
                node: Box::new(Node::raster(
                    "img",
                    chitrakar_doc::RasterRef {
                        resource_id: rid,
                        width: w,
                        height: h,
                        corners,
                    },
                )),
            })
            .unwrap();
            doc.children_of(root).unwrap()[0]
        };
        let varied: Vec<u8> = (0..20 * 20 * 4)
            .map(|i| {
                if i % 4 == 3 {
                    255
                } else {
                    ((i as u64 * 53 + 7) % 251) as u8
                }
            })
            .collect();

        // The rectangle's own corners: the same picture, to the last bit
        // that matters.
        let mut plain = Document::new(30, 30, ColorMode::Rgb);
        let pid = picture(&mut plain, varied.clone(), 20, 20, None);
        let mut cornered = Document::new(30, 30, ColorMode::Rgb);
        let cid = picture(
            &mut cornered,
            varied.clone(),
            20,
            20,
            Some([[0.0, 0.0], [20.0, 0.0], [20.0, 20.0], [0.0, 20.0]]),
        );
        for doc_id in [(&mut plain, pid), (&mut cornered, cid)] {
            doc_id
                .0
                .apply(Command::SetTransform {
                    id: doc_id.1,
                    transform: Transform::translation(5.0, 3.0),
                })
                .unwrap();
        }
        let (a, b) = (render(&plain).unwrap(), render(&cornered).unwrap());
        for (p, q) in a.pixels.iter().zip(&b.pixels) {
            assert!(
                (p.r - q.r).abs() < 1e-5 && (p.a - q.a).abs() < 1e-5,
                "{p:?} against {q:?}"
            );
        }

        // A trapezoid of solid red: inside it is red, outside it is
        // nothing, and a pixel its slanted edge crosses is covered by the
        // part of it inside.
        let red: Vec<u8> = [255u8, 0, 0, 255].repeat(20 * 20);
        let mut doc = Document::new(40, 20, ColorMode::Rgb);
        let id = picture(
            &mut doc,
            red,
            20,
            20,
            Some([[0.0, 0.0], [40.0, 0.0], [30.0, 20.0], [10.0, 20.0]]),
        );
        let s = render(&doc).unwrap();
        assert!(s.get(20, 10).a > 0.999 && s.get(38, 1).a > 0.95);
        assert!(s.get(5, 15).a < 1e-6 && s.get(36, 17).a < 1e-6);
        // The left edge runs x = y / 2: through row 15, from 7.5 to 8, so
        // pixel 7 is a quarter covered.
        let edge = s.get(7, 15).a;
        assert!((edge - 0.25).abs() < 0.02, "an edge pixel covered {edge}");
        // The box is the quad's, and a hit is inside the quad only.
        assert_eq!(
            node_bounds(&doc, id).unwrap(),
            Bounds::Rect(0.0, 0.0, 40.0, 20.0)
        );
        assert_eq!(hit_test(&doc, 20.0, 10.0).unwrap(), Some(id));
        assert_eq!(hit_test(&doc, 25.0, 5.0).unwrap(), Some(id));
        assert_eq!(hit_test(&doc, 3.0, 17.0).unwrap(), None);

        // A fine checker squeezed into the far end of a perspective is
        // its average there, not a moiré of whichever texels a pixel
        // happens to land on.
        let n = 64u32;
        let checker: Vec<u8> = (0..n * n)
            .flat_map(|i| {
                let on = ((i % n) + (i / n)).is_multiple_of(2);
                let v = if on { 255 } else { 0 };
                [v, v, v, 255]
            })
            .collect();
        let mut doc = Document::new(64, 64, ColorMode::Rgb);
        picture(
            &mut doc,
            checker,
            n,
            n,
            // Sixty-four texels into thirteen pixels: no pixel's middle
            // lands on a texel edge, where one bilinear tap would be the
            // average by luck.
            Some([[25.0, 0.0], [38.0, 0.0], [64.0, 64.0], [0.0, 64.0]]),
        );
        let s = render(&doc).unwrap();
        // Half white in light, the average a squeeze should come to.
        for x in 26..37 {
            let p = s.get(x, 2);
            assert!(
                (p.r - 0.5).abs() < 0.12,
                "the far end at {x} is {} rather than the checker's average",
                p.r
            );
        }

        // A bow tie is not a quad, and the picture keeps its rectangle.
        let mut doc = Document::new(30, 30, ColorMode::Rgb);
        let id = picture(
            &mut doc,
            [0u8, 0, 255, 255].repeat(100),
            10,
            10,
            Some([[0.0, 0.0], [10.0, 0.0], [0.0, 10.0], [10.0, 10.0]]),
        );
        assert_eq!(
            node_bounds(&doc, id).unwrap(),
            Bounds::Rect(0.0, 0.0, 10.0, 10.0)
        );
        assert!(render(&doc).unwrap().get(5, 5).a > 0.999);
    }

    /// A picture at half its size is the average of each two texels by
    /// two, exactly.
    ///
    /// That is the claim that earns the sample count: a bilinear tap is
    /// already the average of the two texels either side of it on each
    /// axis, weighted to sum to one, so one tap at the middle of a
    /// two-texel footprint *is* the box average over it — and taps two
    /// texels apart cover any footprint with nothing missed between them.
    /// Asking for one a texel, which is what taking the footprint's
    /// ceiling did, samples the picture twice over and costs four bilinear
    /// taps where one will do.
    ///
    /// Held against the average worked out here rather than against a
    /// tolerance, because the interesting failure is the sample count
    /// dropping *too* far: a single tap over a footprint of four texels
    /// reads two of them and misses two, which is the crawl a shrunk
    /// photograph gets when it moves, and an average that is merely close
    /// would not say which two it read.
    ///
    /// It does not tell the two sample counts apart, and that is worth
    /// saying: the older rule of one tap a texel passes this too. Four
    /// taps spread evenly over a two-texel footprint average to the same
    /// place one at its middle does. So what this pins is the *answer* at
    /// half size, and what pins the count from below is
    /// `a_minified_raster_averages_the_texels_it_skips_over` — hold the
    /// taps at one and that one fails. Between them the count is bracketed
    /// on both sides.
    /// A checker a texel square, shrunk to a fifth and to a ninth and
    /// turned, is the flat grey it averages to everywhere inside it. Drawn
    /// from a level of its pyramid, where the checker has already been
    /// averaged away; drawn from the picture itself, a grid of three or
    /// four taps a side over a footprint of five or nine texels lands on
    /// light and dark unevenly, and the picture is a moiré that crawls as
    /// it moves.
    #[test]
    fn a_fine_checker_shrunk_a_long_way_is_flat_grey() {
        const N: u32 = 360;
        let mut bytes = Vec::with_capacity((N * N * 4) as usize);
        for y in 0..N {
            for x in 0..N {
                let v = if (x + y) % 2 == 0 { 255 } else { 0 };
                bytes.extend_from_slice(&[v, v, v, 255]);
            }
        }
        for (name, scale, turn) in [("a fifth", 0.2f32, 0.3f32), ("a ninth", 0.111, 0.7)] {
            let mut doc = Document::new(80, 80, ColorMode::Rgb);
            let rid = doc.add_resource(N, N, bytes.clone());
            let root = doc.root();
            doc.apply(Command::AddNode {
                parent: root,
                index: 0,
                node: Box::new(Node::raster(
                    "checker",
                    chitrakar_doc::RasterRef {
                        resource_id: rid,
                        width: N,
                        height: N,
                        corners: None,
                    },
                )),
            })
            .unwrap();
            let id = doc.children_of(root).unwrap()[0];
            let (sn, cs) = turn.sin_cos();
            doc.apply(Command::SetTransform {
                id,
                transform: Transform {
                    a: scale * cs,
                    b: scale * sn,
                    c: -scale * sn,
                    d: scale * cs,
                    e: 40.0 - scale * N as f32 * (cs - sn) / 2.0,
                    f: 40.0 - scale * N as f32 * (cs + sn) / 2.0,
                },
            })
            .unwrap();
            let s = render(&doc).unwrap();
            // Well inside the turned square, wherever it lands.
            let (mut lo, mut hi) = (f32::MAX, f32::MIN);
            for y in 30..50 {
                for x in 30..50 {
                    let p = s.get(x, y);
                    lo = lo.min(p.r);
                    hi = hi.max(p.r);
                }
            }
            assert!(
                (lo - 0.5).abs() < 0.01 && (hi - 0.5).abs() < 0.01,
                "{name}: the grey runs from {lo:.4} to {hi:.4}, where it should be 0.5"
            );
        }
    }

    /// An invert, a posterize, a photo filter and a threshold are read
    /// from what a pass prepares — a table a channel, or the level in
    /// light — rather than worked out with powers a pixel, and have to
    /// stay what the formula says: within five hundred-thousandths of
    /// it for the smooth ones, across the deepest shadow where the
    /// encoding is steepest, the middle, white and above white; between
    /// the two steps either side for a posterize, whose table is read
    /// between its entries and so rounds a step's edge off over one
    /// four-thousandth of the light, and exactly the formula's step
    /// everywhere else; and exactly for a threshold, either side of its
    /// level and at it.
    #[test]
    fn a_channel_adjustment_by_table_is_the_adjustment_by_powers() {
        let doc = Document::new(4, 4, ColorMode::Rgb);
        let glass = |r: f32, g: f32, b: f32, a: f32| AuthoredColor::Srgb { r, g, b, a };
        let smooth = [
            Adjustment::Invert { amount: 1.0 },
            Adjustment::Invert { amount: 0.35 },
            Adjustment::Invert { amount: 0.0 },
            Adjustment::PhotoFilter {
                color: glass(0.93, 0.6, 0.1, 1.0),
                density: 0.4,
                preserve_luminosity: false,
            },
            Adjustment::PhotoFilter {
                color: glass(0.2, 0.5, 1.0, 0.7),
                density: 0.9,
                preserve_luminosity: true,
            },
        ];
        let pixel = |r: f32, g: f32, b: f32| LinearRgba {
            r: r * 0.8,
            g: g * 0.8,
            b: b * 0.8,
            a: 0.8,
        };
        let sweep = (0..=3000).map(|i| i as f32 / 2500.0);
        let mut worst = 0.0f32;
        for adj in &smooth {
            let ready = prepare(&doc, adj).expect("prepared");
            assert!(matches!(ready, Prepared::Through(..)));
            for v in sweep.clone() {
                for px in [
                    pixel(v, v * 0.5, 1.0 - v.min(1.0)),
                    pixel(1.0 - v.min(1.0), v, v * v),
                ] {
                    let by_table = apply_adjustment(adj, Some(&ready), px);
                    let by_powers = apply_adjustment(adj, None, px);
                    for (a, b) in [
                        (by_table.r, by_powers.r),
                        (by_table.g, by_powers.g),
                        (by_table.b, by_powers.b),
                    ] {
                        // The most is at the seam of the encoding, where
                        // its straight part meets the power law and an
                        // invert at full strength is at its steepest: a
                        // thousandth of an eight-bit step.
                        let d = (a - b).abs();
                        assert!(d < 5e-5, "{adj:?} at {px:?}: {a} by table, {b} by powers");
                        worst = worst.max(d);
                    }
                    assert_eq!(by_table.a, by_powers.a);
                }
            }
        }
        assert!(worst > 0.0, "the table is read between its entries");
        for levels in [2.0, 4.0, 17.0, 255.0] {
            let adj = Adjustment::Posterize { levels };
            let ready = prepare(&doc, &adj).expect("prepared");
            let steps = posterize_steps(levels);
            let mut rounded = 0;
            for v in sweep.clone() {
                let px = pixel(v, v * 0.5, 1.0 - v.min(1.0));
                let by_table = apply_adjustment(&adj, Some(&ready), px);
                let by_powers = apply_adjustment(&adj, None, px);
                for (c, (a, b)) in [
                    (by_table.r, by_powers.r),
                    (by_table.g, by_powers.g),
                    (by_table.b, by_powers.b),
                ]
                .into_iter()
                .enumerate()
                {
                    let light = [px.r, px.g, px.b][c] / px.a;
                    // The entries either side of the light: between
                    // them, and the formula's own step where both are it.
                    let x = light.clamp(0.0, 1.0) * CURVE_STEPS as f32;
                    let (lo, hi) = (
                        x.floor() / CURVE_STEPS as f32,
                        x.ceil() / CURVE_STEPS as f32,
                    );
                    let (lo, hi) = (
                        posterize_channel(lo, steps) * px.a,
                        posterize_channel(hi, steps) * px.a,
                    );
                    if (lo - hi).abs() < 1e-7 {
                        assert!(
                            (a - b).abs() < 2e-6,
                            "{levels} levels at {light}: {a} by table, {b} by the formula"
                        );
                    } else {
                        assert!(
                            a >= lo.min(hi) - 1e-7 && a <= lo.max(hi) + 1e-7,
                            "{levels} levels at {light}: {a} is not between the steps {lo} and {hi}"
                        );
                        rounded += 1;
                    }
                }
            }
            // Some land in the cell a step's edge falls in, and most do
            // not: at 255 levels a sixteenth of them.
            assert!(
                rounded > 0 && rounded * 8 < 9000,
                "{levels} levels: {rounded} readings on a step's edge"
            );
        }
        for level in [0.0, 0.18, 0.5, 0.73, 1.0] {
            let adj = Adjustment::Threshold { level };
            let ready = prepare(&doc, &adj).expect("prepared");
            let lin = chitrakar_color::srgb_to_linear(level);
            // Either side of the level, at it, and a float's width away.
            let near = [
                lin,
                f32::from_bits(lin.to_bits().saturating_sub(1)),
                f32::from_bits(lin.to_bits().saturating_add(1)),
                lin - 1e-7,
                lin + 1e-7,
                lin - 2e-6,
                lin + 2e-6,
            ];
            for v in sweep.clone().chain(near) {
                for px in [pixel(v, v, v), pixel(v, 0.2, 0.9), pixel(0.1, v, 0.4)] {
                    let by_level = apply_adjustment(&adj, Some(&ready), px);
                    let by_curve = apply_adjustment(&adj, None, px);
                    assert_eq!(
                        by_level.r.to_bits(),
                        by_curve.r.to_bits(),
                        "threshold {level} at {px:?}: {by_level:?} by the level, {by_curve:?} by the curve"
                    );
                }
            }
        }
    }

    /// A curves layer's crossing — into the display encoding, through
    /// the curves, back into light — is read from one table a channel
    /// now rather than worked out with nine powers a pixel. The table
    /// is the exact crossing at each step and read between them, so it
    /// has to stay the exact crossing everywhere: in the deepest shadow,
    /// where the encoding is steepest, across the middle, at white, and
    /// above white, where a channel is carried on by the curve's gain.
    #[test]
    fn a_curves_layer_crosses_by_table_where_the_power_law_would() {
        let adj = Adjustment::Curves {
            points: vec![[0.0, 0.05], [0.3, 0.42], [0.7, 0.66], [1.0, 0.93]],
            red: vec![[0.0, 0.0], [0.5, 0.6], [1.0, 1.0]],
            green: Vec::new(),
            blue: vec![[0.0, 0.1], [0.4, 0.3], [1.0, 0.9]],
        };
        let ready = prepare(&Document::new(1, 1, ColorMode::Rgb), &adj);
        let Some(Prepared::Curves(luts)) = ready.as_ref() else {
            panic!("a curves layer prepares its tables");
        };
        let exact = |v: f32, own: Option<&Vec<f32>>| {
            let through = |x: f32| {
                let m = curve_at(&luts.master, x);
                own.map_or(m, |lut| curve_at(lut, m))
            };
            let inside = v.clamp(0.0, 1.0);
            let white = chitrakar_color::srgb_to_linear(through(1.0));
            chitrakar_color::srgb_to_linear(through(chitrakar_color::linear_to_srgb(inside)))
                + (v - inside).max(0.0) * white
        };
        let mut worst = (0.0f32, 0.0f32);
        for i in 0..=3000 {
            // Dense in the shadows, where the encoding bends hardest.
            let v = (i as f32 / 2000.0).powi(3) * 1.5;
            let got = apply_adjustment(
                &adj,
                ready.as_ref(),
                LinearRgba {
                    r: v,
                    g: v,
                    b: v,
                    a: 1.0,
                },
            );
            for (c, own) in [
                (got.r, luts.red.as_ref()),
                (got.g, None),
                (got.b, luts.blue.as_ref()),
            ] {
                let off = (c - exact(v, own)).abs();
                if off > worst.0 {
                    worst = (off, v);
                }
            }
        }
        assert!(
            worst.0 < 2e-5,
            "the table is {} from the power law at {}",
            worst.0,
            worst.1
        );
    }

    /// An upright picture read one tap a pixel is drawn by rows and
    /// columns — where each reads from worked out once — and that has to
    /// be the same picture, to the bit, as the road every other picture
    /// takes: enlarged, shrunk a little and onto a level of its pyramid,
    /// between pixels, flipped either way, faded, masked, and blended.
    #[test]
    fn an_upright_picture_is_the_same_picture_by_rows_and_columns() {
        const N: u32 = 97;
        let bytes: Vec<u8> = (0..N * 61 * 4)
            .map(|i| ((i as u64 * 53 + 7) % 251) as u8)
            .collect();
        let place = |t: Transform, opacity: f32, masked: bool, blend: BlendMode| {
            let mut doc = Document::new(140, 90, ColorMode::Rgb);
            let rid = doc.add_resource(N, 61, bytes.clone());
            let root = doc.root();
            let mut node = Node::raster(
                "img",
                chitrakar_doc::RasterRef {
                    resource_id: rid,
                    width: N,
                    height: 61,
                    corners: None,
                },
            );
            node.opacity = opacity;
            node.blend = blend;
            if masked {
                node.mask = Some(Mask {
                    kind: MaskKind::Vector {
                        shape: VectorShape::Ellipse { rx: 40.0, ry: 25.0 },
                        transform: Transform::translation(60.0, 40.0),
                    },
                    invert: false,
                    feather: 0.0,
                });
            }
            doc.apply(Command::AddNode {
                parent: root,
                index: 0,
                node: Box::new(node),
            })
            .unwrap();
            let id = doc.children_of(root).unwrap()[0];
            doc.apply(Command::SetTransform { id, transform: t })
                .unwrap();
            doc
        };
        let at = |a: f32, d: f32, e: f32, f: f32| Transform {
            a,
            d,
            e,
            f,
            ..Default::default()
        };
        let pages = [
            (
                "enlarged",
                at(1.37, 1.37, 3.3, 2.6),
                1.0,
                false,
                BlendMode::Normal,
            ),
            (
                "shrunk a little",
                at(0.71, 0.83, 5.5, 4.25),
                1.0,
                false,
                BlendMode::Normal,
            ),
            (
                "onto the half",
                at(0.4, 0.4, 7.2, 1.9),
                1.0,
                false,
                BlendMode::Normal,
            ),
            (
                "onto the quarter",
                at(0.23, 0.26, 1.1, 0.6),
                1.0,
                false,
                BlendMode::Normal,
            ),
            (
                "flipped across",
                at(-1.2, 1.1, 130.4, 3.0),
                1.0,
                false,
                BlendMode::Normal,
            ),
            (
                "flipped down",
                at(0.9, -0.95, 4.0, 70.7),
                1.0,
                false,
                BlendMode::Normal,
            ),
            (
                "faded",
                at(1.1, 1.1, 2.5, 2.5),
                0.45,
                false,
                BlendMode::Normal,
            ),
            (
                "masked",
                at(1.3, 1.2, 0.5, 0.5),
                1.0,
                true,
                BlendMode::Normal,
            ),
            (
                "blended",
                at(1.05, 1.15, 6.6, 3.3),
                1.0,
                false,
                BlendMode::Multiply,
            ),
        ];
        for (name, t, opacity, masked, blend) in pages {
            let doc = place(t, opacity, masked, blend);
            BY_ROWS.with(|b| b.set(false));
            let general = render(&doc).unwrap();
            BY_ROWS.with(|b| b.set(true));
            let rows = render(&doc).unwrap();
            assert!(
                rows.pixels.iter().any(|p| p.a > 0.0),
                "{name}: drawn at all"
            );
            for (i, (p, q)) in general.pixels.iter().zip(&rows.pixels).enumerate() {
                assert!(
                    p.r.to_bits() == q.r.to_bits()
                        && p.g.to_bits() == q.g.to_bits()
                        && p.b.to_bits() == q.b.to_bits()
                        && p.a.to_bits() == q.a.to_bits(),
                    "{name}: pixel {i} is {q:?} by rows and {p:?} the other way"
                );
            }
        }
    }

    /// A rounded rectangle's distance skips `hypot` along its sides,
    /// where one of the two lengths is nothing — and is the same number,
    /// to the bit, as the formula that always called it, everywhere
    /// round the shape, inside, outside, and at its corners.
    #[test]
    fn a_rounded_rectangles_distance_is_the_same_without_the_call() {
        let reference = |width: f32, height: f32, radius: f32, x: f32, y: f32| {
            let (hw, hh) = (width / 2.0, height / 2.0);
            let r = corner_radius(width, height, radius);
            let qx = (x - hw).abs() - (hw - r);
            let qy = (y - hh).abs() - (hh - r);
            qx.max(0.0).hypot(qy.max(0.0)) + qx.max(qy).min(0.0) - r
        };
        for (w, h, r) in [
            (120.0f32, 80.0f32, 6.0f32),
            (40.0, 40.0, 20.0),
            (30.0, 12.0, 0.0),
            (9.5, 70.25, 3.3),
        ] {
            let mut y = -12.0f32;
            while y < h + 12.0 {
                let mut x = -12.0f32;
                while x < w + 12.0 {
                    let got = rounded_rect_distance(w, h, r, x, y);
                    let want = reference(w, h, r, x, y);
                    assert_eq!(got.to_bits(), want.to_bits(), "{w}x{h} r{r} at ({x}, {y})");
                    x += 0.37;
                }
                y += 0.41;
            }
        }
    }

    /// Text is shaped and rasterized once and kept — by the face and the
    /// string, by what the block says, the scale and where its origin
    /// falls between pixels — so nothing kept may ever stand in for what
    /// a change asks for: a block drawn, then changed in its words, its
    /// size, the scale it is seen at and its place between the pixels,
    /// is at every step the page a fresh document draws.
    #[test]
    fn text_kept_from_one_frame_is_never_another_frames_text() {
        let f = chitrakar_doc::fixture::everything();
        let NodeKind::Text(base) = f.doc.node(f.words).unwrap().kind.clone() else {
            panic!("the fixture's words are text");
        };
        let page = |spec: &chitrakar_doc::TextSpec, t: Transform| {
            let mut doc = Document::new(220, 90, ColorMode::Rgb);
            let root = doc.root();
            let mut n = Node::text("t", spec.clone());
            n.transform = t;
            doc.apply(Command::AddNode {
                parent: root,
                index: 0,
                node: Box::new(n),
            })
            .unwrap();
            doc
        };
        let mut spec = base.clone();
        spec.text = "Kept, and drawn again".into();
        spec.size = 18.0;
        let mut steps = vec![(spec.clone(), Transform::translation(6.0, 8.0))];
        let mut changed = spec.clone();
        changed.text = "Kept, and drawn agaim".into();
        steps.push((changed.clone(), Transform::translation(6.0, 8.0)));
        changed.size = 19.5;
        steps.push((changed.clone(), Transform::translation(6.0, 8.0)));
        steps.push((
            changed.clone(),
            Transform {
                a: 1.3,
                d: 1.3,
                e: 6.0,
                f: 8.0,
                ..Default::default()
            },
        ));
        steps.push((changed.clone(), Transform::translation(6.37, 8.61)));
        steps.push((spec.clone(), Transform::translation(6.0, 8.0)));
        for (i, (spec, t)) in steps.iter().enumerate() {
            // Drawn twice, the second from what the first kept, and
            // against a raster made from nothing.
            let doc = page(spec, *t);
            let first = render(&doc).unwrap();
            let again = render(&doc).unwrap();
            let (raster, scale) = text_raster(spec, *t);
            let (kept, kept_scale) = text_raster_kept(spec, *t);
            assert_eq!(
                scale.to_bits(),
                kept_scale.to_bits(),
                "step {i}: the same scale"
            );
            assert_eq!(
                raster.coverage, kept.coverage,
                "step {i}: the raster kept is the raster made"
            );
            assert_eq!(first.pixels.len(), again.pixels.len());
            assert!(
                first.pixels.iter().zip(&again.pixels).all(|(p, q)| p == q),
                "step {i}: drawn again from what was kept, it is the same page"
            );
        }
    }

    #[test]
    fn a_picture_at_half_its_size_is_each_two_texels_averaged() {
        const N: u32 = 32;
        // Values with no pattern two neighbours could stand in for, so an
        // average over the wrong pair is a different number.
        let bytes: Vec<u8> = (0..N * N * 4)
            .map(|i| ((i as u64 * 53 + 7) % 251) as u8)
            .collect();
        let mut doc = Document::new(N / 2, N / 2, ColorMode::Rgb);
        let rid = doc.add_resource(N, N, bytes.clone());
        let root = doc.root();
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(Node::raster(
                "img",
                chitrakar_doc::RasterRef {
                    resource_id: rid,
                    width: N,
                    height: N,
                    corners: None,
                },
            )),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id,
            transform: Transform {
                a: 0.5,
                d: 0.5,
                ..Default::default()
            },
        })
        .unwrap();
        let s = render(&doc).unwrap();

        // The source, premultiplied in linear light, which is the space the
        // average is taken in.
        let texel = |x: u32, y: u32| {
            let at = ((y * N + x) * 4) as usize;
            let a = bytes[at + 3] as f32 / 255.0;
            [
                chitrakar_color::srgb_to_linear(bytes[at] as f32 / 255.0) * a,
                chitrakar_color::srgb_to_linear(bytes[at + 1] as f32 / 255.0) * a,
                chitrakar_color::srgb_to_linear(bytes[at + 2] as f32 / 255.0) * a,
                a,
            ]
        };
        // The edges of the picture are where the sampler clamps, so the
        // inside is what the claim is about.
        for y in 1..(N / 2 - 1) {
            for x in 1..(N / 2 - 1) {
                let mut want = [0.0f32; 4];
                for j in 0..2 {
                    for i in 0..2 {
                        let t = texel(x * 2 + i, y * 2 + j);
                        for k in 0..4 {
                            want[k] += t[k] / 4.0;
                        }
                    }
                }
                let got = s.get(x, y);
                for (k, (a, b)) in [
                    (got.r, want[0]),
                    (got.g, want[1]),
                    (got.b, want[2]),
                    (got.a, want[3]),
                ]
                .iter()
                .enumerate()
                {
                    assert!(
                        (a - b).abs() < 1e-5,
                        "({x},{y}) channel {k}: {a:.6} against the {b:.6} its four texels average to"
                    );
                }
            }
        }
    }

    #[test]
    fn a_minified_raster_averages_the_texels_it_skips_over() {
        // Four-texel stripes shrunk to an eighth. Every device pixel spans
        // a whole period, so the honest answer is the average — mid grey.
        // One bilinear sample instead lands in whichever stripe the grid
        // happens to fall on and reads black or white, which is what makes
        // a shrunk photograph crawl when it moves. (Stripes rather than a
        // checkerboard: a one-texel checkerboard averages to grey under a
        // single bilinear tap too, and so would prove nothing.)
        const N: u32 = 64;
        let mut rgba8 = Vec::with_capacity((N * N * 4) as usize);
        for y in 0..N {
            for x in 0..N {
                let _ = y;
                let v = if (x / 3) % 2 == 0 { 0u8 } else { 255u8 };
                rgba8.extend_from_slice(&[v, v, v, 255]);
            }
        }
        let mut doc = Document::new(16, 16, ColorMode::Rgb);
        let root = doc.root();
        let id = doc.add_resource(N, N, rgba8);
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(Node::raster(
                "img",
                chitrakar_doc::RasterRef {
                    resource_id: id,
                    width: N,
                    height: N,
                    corners: None,
                },
            )),
        })
        .unwrap();
        let node = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id: node,
            transform: Transform {
                a: 0.125,
                d: 0.125,
                ..Default::default()
            },
        })
        .unwrap();
        let s = render(&doc).unwrap();
        // Linear-light average of black and white is 0.5, whatever sRGB
        // makes of it at the display edge.
        let inside: Vec<f32> = (1..7)
            .flat_map(|y| (1..7).map(move |x| (x, y)))
            .map(|(x, y)| s.get(x, y).r)
            .collect();
        let lo = inside.iter().cloned().fold(f32::MAX, f32::min);
        let hi = inside.iter().cloned().fold(f32::MIN, f32::max);
        // Four taps across eight texels do not fully resolve a six-texel
        // period, so the reading wobbles a little either side of the
        // average. A single sample swings the whole way from black to
        // white, which is the difference this is about.
        assert!(
            (lo - 0.5).abs() < 0.15 && (hi - 0.5).abs() < 0.15,
            "every pixel should read near the average, got {lo}..{hi}"
        );
    }

    #[test]
    fn magnified_raster_interpolates_between_texels() {
        // A black and a white texel blown up 8x. Halfway between their
        // centres the blit must land between them; nearest sampling would
        // return one or the other and stair-step the boundary.
        let mut doc = Document::new(16, 8, ColorMode::Rgb);
        let root = doc.root();
        let rgba8 = vec![0, 0, 0, 255, /**/ 255, 255, 255, 255];
        let id = doc.add_resource(2, 1, rgba8);
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(Node::raster(
                "img",
                chitrakar_doc::RasterRef {
                    resource_id: id,
                    width: 2,
                    height: 1,
                    corners: None,
                },
            )),
        })
        .unwrap();
        let node = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id: node,
            transform: Transform {
                a: 8.0,
                d: 8.0,
                ..Default::default()
            },
        })
        .unwrap();

        let s = render(&doc).unwrap();
        // Texel centres map to x = 4 and x = 12; x = 8 is the midpoint.
        let mid = s.get(8, 4).to_srgb8();
        assert!(
            mid[0] > 100 && mid[0] < 200,
            "midpoint should be a blend, got {mid:?}"
        );
        assert_eq!(s.get(0, 4).to_srgb8()[0], 0, "clamped to black at the edge");
        assert_eq!(
            s.get(15, 4).to_srgb8()[0],
            255,
            "clamped to white at the edge"
        );
        // Ramp is monotonic across the interpolated span.
        let ramp: Vec<u8> = (4..=12).map(|x| s.get(x, 4).to_srgb8()[0]).collect();
        assert!(
            ramp.windows(2).all(|w| w[1] >= w[0]),
            "ramp should rise monotonically, got {ramp:?}"
        );
    }

    /// A picture laid down at its own size, on whole pixels, is its own
    /// texels — each one exactly, not nearly.
    ///
    /// That is what makes the fast path in the blit legitimate. A sample
    /// taken at a texel's own centre lands with nothing either side of it
    /// to mix in, so both interpolations are between a value and itself,
    /// and `a + (b - a) * 0` is `a`. The four fetches and three
    /// interpolations come out at the first fetch, so it takes that
    /// directly — and a photograph opened and looked at, or exported, is
    /// this case and not the general one.
    ///
    /// Asked of the values rather than of the arithmetic: every pixel of
    /// the page is held against the source byte it came from, converted
    /// the one way the engine converts. An off-by-one in the texel picked,
    /// or a sample half a pixel out, moves the picture and fails here —
    /// where a tolerance over the whole page would not notice a shift by
    /// one in a photograph of smooth things.
    #[test]
    fn a_picture_at_its_own_size_is_its_own_texels() {
        let (w, h) = (11u32, 7u32);
        // Bytes with no pattern a neighbour could stand in for, so a
        // sample taken one texel over is a different number.
        let bytes: Vec<u8> = (0..w * h * 4)
            .map(|i| ((i as u64 * 37 + 11) % 251) as u8)
            .collect();
        let mut doc = Document::new(20, 16, ColorMode::Rgb);
        let rid = doc.add_resource(w, h, bytes.clone());
        let root = doc.root();
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(Node::raster(
                "photo",
                chitrakar_doc::RasterRef {
                    resource_id: rid,
                    width: w,
                    height: h,
                    corners: None,
                },
            )),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        let (ox, oy) = (4u32, 3u32);
        doc.apply(Command::SetTransform {
            id,
            transform: Transform::translation(ox as f32, oy as f32),
        })
        .unwrap();
        let s = render(&doc).unwrap();
        for ty in 0..h {
            for tx in 0..w {
                let at = ((ty * w + tx) * 4) as usize;
                let a = bytes[at + 3] as f32 / 255.0;
                let want = LinearRgba {
                    r: chitrakar_color::srgb_to_linear(bytes[at] as f32 / 255.0) * a,
                    g: chitrakar_color::srgb_to_linear(bytes[at + 1] as f32 / 255.0) * a,
                    b: chitrakar_color::srgb_to_linear(bytes[at + 2] as f32 / 255.0) * a,
                    a,
                };
                let got = s.get(tx + ox, ty + oy);
                assert_eq!(
                    (got.r, got.g, got.b, got.a),
                    (want.r, want.g, want.b, want.a),
                    "texel ({tx},{ty}) came out as something else"
                );
            }
        }
        // And nothing outside it: the picture's own box and no more.
        assert_eq!(s.get(ox - 1, oy).a, 0.0, "nothing to the left of it");
        assert_eq!(s.get(ox + w, oy).a, 0.0, "nor to the right");
        assert_eq!(s.get(ox, oy - 1).a, 0.0, "nor above");
        assert_eq!(s.get(ox, oy + h).a, 0.0, "nor below");
    }

    #[test]
    fn raster_edge_is_antialiased_on_a_half_pixel() {
        // The image outline is a rect in local space, so it gets the same
        // exact coverage a rect fill does instead of a hard jagged border.
        let mut doc = Document::new(8, 8, ColorMode::Rgb);
        let root = doc.root();
        let id = doc.add_resource(2, 2, vec![255; 16]);
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(Node::raster(
                "img",
                chitrakar_doc::RasterRef {
                    resource_id: id,
                    width: 2,
                    height: 2,
                    corners: None,
                },
            )),
        })
        .unwrap();
        let node = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id: node,
            transform: Transform::translation(2.5, 2.0),
        })
        .unwrap();

        let s = render(&doc).unwrap();
        assert!(
            (s.get(2, 2).a - 0.5).abs() < 0.05,
            "half-covered column, got {}",
            s.get(2, 2).a
        );
        assert_eq!(s.get(3, 2).a, 1.0, "fully covered column stays opaque");
    }

    #[test]
    fn raster_mask_uses_luminance() {
        let mut doc = Document::new(4, 4, ColorMode::Rgb);
        let root = doc.root();
        // 2×2 mask: white / black in the top row → show / hide.
        let mask_px = vec![
            255, 255, 255, 255, /**/ 0, 0, 0, 255, //
            255, 255, 255, 255, /**/ 0, 0, 0, 255,
        ];
        let mask_id = doc.add_resource(2, 2, mask_px);
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: filled_rect("r", 4.0, 4.0, RED),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetMask {
            id,
            mask: Some(Box::new(Mask {
                kind: MaskKind::Raster {
                    resource_id: mask_id,
                    width: 2,
                    height: 2,
                    // Scale the 2×2 mask over the 4×4 canvas.
                    transform: Transform {
                        a: 2.0,
                        b: 0.0,
                        c: 0.0,
                        d: 2.0,
                        e: 0.0,
                        f: 0.0,
                    },
                },
                invert: false,
                feather: 0.0,
            })),
        })
        .unwrap();

        let s = render(&doc).unwrap();
        assert_eq!(s.get(0, 0).to_srgb8(), [255, 0, 0, 255], "white shows");
        assert_eq!(s.get(3, 0).a, 0.0, "black hides");
    }

    #[test]
    fn blur_layer_bleeds_past_shape_edges() {
        let mut doc = Document::new(32, 32, ColorMode::Rgb);
        let root = doc.root();
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: filled_rect("r", 8.0, 8.0, RED),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id,
            transform: Transform::translation(12.0, 12.0),
        })
        .unwrap();

        let crisp = render(&doc).unwrap();
        assert_eq!(crisp.get(10, 16).a, 0.0, "outside the rect before blur");

        doc.apply(Command::AddNode {
            parent: root,
            index: 1,
            node: Box::new(Node::filter(
                "blur",
                chitrakar_doc::Filter::GaussianBlur { sigma: 3.0 },
            )),
        })
        .unwrap();
        let blurred = render(&doc).unwrap();
        assert!(blurred.get(10, 16).a > 0.0, "blur bleeds outward");
        assert!(
            blurred.get(15, 16).r < crisp.get(15, 16).r,
            "edge softened inside too"
        );
        assert_eq!(
            node_bounds(&doc, root).unwrap(),
            Bounds::Everything,
            "filters invalidate the whole canvas"
        );
    }

    #[test]
    fn sharpen_boosts_edge_contrast_without_touching_flat_areas() {
        let mut doc = Document::new(24, 24, ColorMode::Rgb);
        let root = doc.root();
        let grey = AuthoredColor::Srgb {
            r: 0.5,
            g: 0.5,
            b: 0.5,
            a: 1.0,
        };
        // Full-canvas grey with a brighter square in the middle.
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: filled_rect("bg", 24.0, 24.0, grey),
        })
        .unwrap();
        doc.apply(Command::AddNode {
            parent: root,
            index: 1,
            node: filled_rect(
                "sq",
                8.0,
                8.0,
                AuthoredColor::Srgb {
                    r: 0.8,
                    g: 0.8,
                    b: 0.8,
                    a: 1.0,
                },
            ),
        })
        .unwrap();
        let sq = doc.children_of(root).unwrap()[1];
        doc.apply(Command::SetTransform {
            id: sq,
            transform: Transform::translation(8.0, 8.0),
        })
        .unwrap();
        let before = render(&doc).unwrap();

        doc.apply(Command::AddNode {
            parent: root,
            index: 2,
            node: Box::new(Node::filter(
                "sharpen",
                chitrakar_doc::Filter::Sharpen {
                    sigma: 1.5,
                    amount: 1.0,
                },
            )),
        })
        .unwrap();
        let after = render(&doc).unwrap();

        // Just inside the bright square's edge gets brighter; the flat
        // far-away background stays put.
        assert!(
            after.get(9, 12).r > before.get(9, 12).r + 1e-3,
            "edge overshoot inside the square"
        );
        assert!(
            (after.get(2, 2).r - before.get(2, 2).r).abs() < 1e-4,
            "flat region unchanged"
        );
    }

    #[test]
    fn raster_object_renders_and_hit_tests() {
        let mut doc = Document::new(8, 8, ColorMode::Rgb);
        let root = doc.root();
        // 2×2 image: opaque red, semi-transparent white bottom-right.
        let rgba8 = vec![
            255, 0, 0, 255, /**/ 255, 0, 0, 255, //
            255, 0, 0, 255, /**/ 255, 255, 255, 128,
        ];
        let id = doc.add_resource(2, 2, rgba8);
        let raster = chitrakar_doc::RasterRef {
            resource_id: id,
            width: 2,
            height: 2,
            corners: None,
        };
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(Node::raster("img", raster)),
        })
        .unwrap();
        let node = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id: node,
            transform: Transform::translation(3.0, 3.0),
        })
        .unwrap();

        let s = render(&doc).unwrap();
        assert_eq!(s.get(3, 3).to_srgb8(), [255, 0, 0, 255]);
        assert_eq!(s.get(4, 4).to_srgb8()[3], 128, "alpha preserved");
        assert_eq!(s.get(0, 0).a, 0.0, "outside image untouched");

        assert_eq!(hit_test(&doc, 4.5, 4.5).unwrap(), Some(node));
        assert_eq!(hit_test(&doc, 1.0, 1.0).unwrap(), None);
    }

    #[test]
    fn closed_path_fills_by_even_odd_and_hit_tests() {
        let mut doc = Document::new(20, 20, ColorMode::Rgb);
        let root = doc.root();
        // Concave arrowhead: (0,0) (16,8) (0,16) (6,8) — the notch at the
        // left must stay empty under even-odd.
        let mut node = Node::vector(
            "arrow",
            VectorShape::Path {
                points: vec![[0.0, 0.0], [16.0, 8.0], [0.0, 16.0], [6.0, 8.0]],
                closed: true,
                smooth: false,
                handles: Vec::new(),
                subpaths: Vec::new(),
            },
        );
        if let NodeKind::Vector { fill, .. } = &mut node.kind {
            *fill = Some(RED);
        }
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(node),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id,
            transform: Transform::translation(2.0, 2.0),
        })
        .unwrap();

        let s = render(&doc).unwrap();
        // Body of the arrow (doc space): local (10,8) -> doc (12,10).
        assert_eq!(s.get(12, 10).to_srgb8(), [255, 0, 0, 255], "inside filled");
        // The concave notch: local (2,8) -> doc (4,10) is outside the fill.
        assert_eq!(s.get(4, 10).a, 0.0, "concave notch stays empty");
        assert_eq!(s.get(19, 19).a, 0.0, "outside stays empty");

        assert_eq!(hit_test(&doc, 12.0, 10.0).unwrap(), Some(id));
        assert_eq!(hit_test(&doc, 4.0, 10.0).unwrap(), None);
        assert_eq!(
            node_bounds(&doc, id).unwrap(),
            Bounds::Rect(2.0, 2.0, 18.0, 18.0)
        );
    }

    #[test]
    fn text_object_renders_ink_and_hit_tests() {
        let mut doc = Document::new(200, 80, ColorMode::Rgb);
        let root = doc.root();
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(Node::text(
                "label",
                chitrakar_doc::TextSpec::new("Hi", 48.0, RED),
            )),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id,
            transform: Transform::translation(10.0, 10.0),
        })
        .unwrap();

        let s = render(&doc).unwrap();
        let ink: u32 = (0..80)
            .flat_map(|y| (0..200).map(move |x| (x, y)))
            .filter(|&(x, y)| s.get(x, y).a > 0.5)
            .count() as u32;
        assert!(ink > 100, "glyphs left substantial ink, got {ink} px");
        // Ink is red (the fill), and confined to the text bounds.
        let Bounds::Rect(bx0, by0, bx1, by1) = node_bounds(&doc, id).unwrap() else {
            panic!("rect bounds");
        };
        assert!(bx0 >= 9.0 && by0 >= 9.0 && bx1 < 200.0 && by1 < 80.0);
        for y in 0..80 {
            for x in 0..200 {
                if s.get(x, y).a > 0.0 {
                    let px = s.get(x, y).to_srgb8();
                    assert!(px[0] >= px[1] && px[0] >= px[2], "ink is red");
                    assert!(
                        (x as f32) >= bx0 - 1.0
                            && (x as f32) <= bx1 + 1.0
                            && (y as f32) >= by0 - 1.0
                            && (y as f32) <= by1 + 1.0,
                        "ink inside bounds"
                    );
                }
            }
        }

        // The block's box is the click target.
        assert_eq!(hit_test(&doc, bx0 + 2.0, by0 + 2.0).unwrap(), Some(id));
        assert_eq!(hit_test(&doc, 190.0, 70.0).unwrap(), None);

        // Editing the text through SetKind grows the bounds (live object).
        doc.apply(Command::SetKind {
            id,
            kind: Box::new(NodeKind::Text(chitrakar_doc::TextSpec::new(
                "Hi there", 48.0, RED,
            ))),
        })
        .unwrap();
        let Bounds::Rect(_, _, wider, _) = node_bounds(&doc, id).unwrap() else {
            panic!("rect bounds");
        };
        assert!(wider > bx1, "longer text widens bounds");
    }

    #[test]
    fn smooth_path_bulges_past_the_straight_chord() {
        let mut doc = Document::new(40, 40, ColorMode::Rgb);
        let root = doc.root();
        // A wide triangle; smoothing the closed path should bow the long
        // bottom edge outward (below the straight chord).
        let make = |smooth| {
            let mut node = Node::vector(
                "tri",
                VectorShape::Path {
                    points: vec![[0.0, 0.0], [30.0, 0.0], [15.0, 20.0]],
                    closed: true,
                    smooth,
                    handles: Vec::new(),
                    subpaths: Vec::new(),
                },
            );
            if let NodeKind::Vector { fill, .. } = &mut node.kind {
                *fill = Some(RED);
            }
            Box::new(node)
        };
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: make(false),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id,
            transform: Transform::translation(5.0, 5.0),
        })
        .unwrap();
        let sharp = render(&doc).unwrap();

        doc.apply(Command::SetKind {
            id,
            kind: Box::new(NodeKind::Vector {
                shape: VectorShape::Path {
                    points: vec![[0.0, 0.0], [30.0, 0.0], [15.0, 20.0]],
                    closed: true,
                    smooth: true,
                    handles: Vec::new(),
                    subpaths: Vec::new(),
                },
                fill: Some(RED),
                stroke: None,
                gradient: None,
            }),
        })
        .unwrap();
        let smooth = render(&doc).unwrap();

        // A probe between the straight edge (0,0)->(30,0) and outside it:
        // doc (20, 3) is above y=5 line only reachable when the top edge
        // bows upward — pick the left edge midpoint instead: chord from
        // (0,0) to (15,20) passes through local (7.5,10) = doc (12.5,15);
        // just outside it, local (5.5,10) = doc (10.5,15).
        assert_eq!(sharp.get(10, 15).a, 0.0, "outside the straight chord");
        assert!(
            smooth.get(10, 15).a > 0.0,
            "smooth spline bows past the chord"
        );
        // Both agree deep inside.
        assert_eq!(sharp.get(20, 12).to_srgb8(), smooth.get(20, 12).to_srgb8());

        // Bounds account for overshoot beyond the anchor box.
        let Bounds::Rect(_, y0, _, y1) = node_bounds(&doc, id).unwrap() else {
            panic!("rect bounds expected");
        };
        assert!(
            y0 < 5.0 || y1 > 25.0,
            "spline overshoot in bounds ({y0}..{y1})"
        );
    }

    #[test]
    fn open_path_strokes_as_centered_line_art() {
        let mut doc = Document::new(24, 24, ColorMode::Rgb);
        let root = doc.root();
        // A "V" polyline, stroke only.
        let mut node = Node::vector(
            "v",
            VectorShape::Path {
                points: vec![[0.0, 0.0], [8.0, 16.0], [16.0, 0.0]],
                closed: false,
                smooth: false,
                handles: Vec::new(),
                subpaths: Vec::new(),
            },
        );
        if let NodeKind::Vector { stroke, .. } = &mut node.kind {
            *stroke = Some(chitrakar_doc::Stroke {
                color: AuthoredColor::Srgb {
                    r: 0.0,
                    g: 1.0,
                    b: 0.0,
                    a: 1.0,
                },
                width: 4.0,
                widths: Vec::new(),
                dash: Vec::new(),
                dash_offset: 0.0,
                cap: Default::default(),
                join: Default::default(),
                start_marker: Default::default(),
                end_marker: Default::default(),
                align: None,
            });
        }
        doc.apply(Command::AddNode {
            parent: root,
            index: 0,
            node: Box::new(node),
        })
        .unwrap();
        let id = doc.children_of(root).unwrap()[0];
        doc.apply(Command::SetTransform {
            id,
            transform: Transform::translation(4.0, 4.0),
        })
        .unwrap();

        let s = render(&doc).unwrap();
        // Bottom vertex local (8,16) -> doc (12,20): on the line.
        assert_eq!(s.get(12, 20).to_srgb8(), [0, 255, 0, 255], "vertex stroked");
        // Interior of the V (doc (12,8)) is far from both segments: empty.
        assert_eq!(s.get(12, 8).a, 0.0, "V interior not filled");
        // No implicit closing segment across the top for open paths.
        assert_eq!(s.get(12, 4).a, 0.0, "open path has no closing edge");

        assert_eq!(
            hit_test(&doc, 12.0, 20.0).unwrap(),
            Some(id),
            "stroke clickable"
        );
        assert_eq!(hit_test(&doc, 12.0, 8.0).unwrap(), None);

        // Bounds include the centered stroke's overhang.
        let Bounds::Rect(x0, y0, _, y1) = node_bounds(&doc, id).unwrap() else {
            panic!("expected rect bounds");
        };
        assert!(
            x0 < 4.0 && y0 < 4.0 && y1 > 20.0,
            "stroke overhang in bounds"
        );
    }

    /// A rectangle's stroke: exact along its runs, and round where it
    /// turns a corner.
    ///
    /// The band used to be sampled sixteen to a pixel like any other
    /// shape, so its edges came out in quarters — a hairline eight
    /// tenths of a pixel over a boundary was drawn as three quarters of
    /// it, which is visible on a thin stroke and was the one place the
    /// renderer that every other is held against was the coarser of
    /// them. The band is one rectangle less another, and each of those
    /// is the product of two 1-D overlaps the fill already had exact.
    ///
    /// Away from the corners only. A band is a range of *distances*, so
    /// it turns a corner in a quarter circle of its own reach even on a
    /// square-cornered rectangle; two rectangles differenced have square
    /// corners and would fill in what the curve leaves out.
    #[test]
    fn a_rects_stroke_is_exact_along_its_runs_and_round_at_its_corners() {
        let banded = |width: f32, at: f32| {
            let mut doc = Document::new(40, 24, ColorMode::Rgb);
            let root = doc.root();
            let mut node = Node::vector(
                "outline",
                VectorShape::Rect {
                    width: 20.0,
                    height: 10.0,
                    radius: 0.0,
                },
            );
            if let NodeKind::Vector { stroke, .. } = &mut node.kind {
                *stroke = Some(chitrakar_doc::Stroke {
                    color: AuthoredColor::Srgb {
                        r: 1.0,
                        g: 1.0,
                        b: 1.0,
                        a: 1.0,
                    },
                    width,
                    widths: Vec::new(),
                    dash: Vec::new(),
                    dash_offset: 0.0,
                    cap: Default::default(),
                    join: Default::default(),
                    start_marker: Default::default(),
                    end_marker: Default::default(),
                    align: Some(chitrakar_doc::StrokeAlign::Centre),
                });
            }
            doc.apply(Command::AddNode {
                parent: root,
                index: 0,
                node: Box::new(node),
            })
            .unwrap();
            let id = doc.children_of(root).unwrap()[0];
            doc.apply(Command::SetTransform {
                id,
                transform: Transform::translation(at, 7.0),
            })
            .unwrap();
            render(&doc).unwrap()
        };

        // A band 1.5715 wide, centred on the left edge at x=10: it runs
        // from 9.2 to 10.79, so the pixel at 9 is eight tenths covered
        // and the one at 10 is a little under four fifths. Sampled four
        // to a side those were three quarters each.
        let s = banded(1.5715, 10.0);
        let row = 12;
        assert!(
            (s.get(9, row).a - 0.7858).abs() < 0.002,
            "the near pixel is exactly what the band covers ({})",
            s.get(9, row).a
        );
        assert!(
            (s.get(10, row).a - 0.7857).abs() < 0.002,
            "and so is the far one ({})",
            s.get(10, row).a
        );

        // The same band a fifth of a pixel along: the two pixels take
        // their share of it, which quarters cannot say either.
        let s = banded(2.0, 10.2);
        assert!(
            (s.get(9, row).a - 0.8).abs() < 0.002 && (s.get(11, row).a - 0.2).abs() < 0.002,
            "a fifth of a pixel is a fifth ({} {})",
            s.get(9, row).a,
            s.get(11, row).a
        );

        // And the corner is a curve. A band four wide reaches two pixels
        // out, so the outer corner of the rectangle at (10,7) is a
        // quarter circle of radius two about that point: the pixel at
        // (8,5) has its near corner inside it and its far corner out, so
        // it is partly covered. Squared off it would be covered whole.
        let s = banded(4.0, 10.0);
        let corner = s.get(8, 5).a;
        assert!(
            corner > 0.05 && corner < 0.9,
            "the corner is a curve rather than a square ({corner})"
        );
        // The run beside it is whole, which says the band is there at
        // all and that the corner is not simply missing.
        assert!(
            (s.get(12, 5).a - 1.0).abs() < 0.002,
            "the band itself is whole along its run ({})",
            s.get(12, 5).a
        );
    }

